
"use client";

import { useState } from "react";
import { validateField } from "../core/validate";

export const useForm = (fields, customHandlers = {}) => {
  // =========================
  // 🔥 FLATTEN FIELDS (GROUP SUPPORT)
  // =========================
  const getAllFields = () => {
    let all = {};

    Object.entries(fields).forEach(([key, field]) => {
      if (field.type === "group") {
        Object.assign(all, field.fields);
      } else {
        all[key] = field;
      }
    });

    return all;
  };

  const allFields = getAllFields();

  // =========================
  // ✅ INITIAL VALUES
  // =========================
  const getInitialValues = () => {
    const initial = {};

    Object.entries(allFields).forEach(([key, field]) => {
      if (field.type === "hidden") {
        initial[key] =
          typeof field.value === "function"
            ? field.value()
            : field.value ?? "";
      } else {
        initial[key] = "";
      }
    });

    return initial;
  };

  // =========================
  // ✅ INITIAL VISIBILITY
  // Build visibility map from schema's `hidden` flag.
  // hidden: true  → starts hidden (false)
  // hidden: false / missing → starts visible (true)
  // =========================
  const getInitialVisibility = () => {
    const vis = {};
    Object.entries(allFields).forEach(([key, field]) => {
      vis[key] = field.hidden ? false : true;
    });
    return vis;
  };

  const [values, setValues] = useState(getInitialValues);
  const [errors, setErrors] = useState({});
  const [dynamicOptions, setDynamicOptions] = useState({});
  const [visibleFields, setVisibleFields] = useState(getInitialVisibility);

  // =========================
  // 🔧 HELPERS
  // =========================
  const setOptions = (fieldName, options) => {
    setDynamicOptions((prev) => ({ ...prev, [fieldName]: options }));
  };

  const setVisible = (fieldName, isVisible) => {
    setVisibleFields((prev) => ({ ...prev, [fieldName]: isVisible }));
  };

  const setValue = (fieldName, value) => {
    setValues((prev) => ({ ...prev, [fieldName]: value }));
  };

  // =========================
  // 🔥 RUN EVENTS ENGINE
  // Processes all events on a field for a given trigger.
  // =========================
  const runEvents = async (fieldName, triggerType, value, updatedValues) => {
    const field = allFields[fieldName];
    if (!field?.events) return;

    for (const event of field.events) {
      if (event.trigger !== triggerType) continue;

      switch (event.action) {
        // ✅ SHOW FIELD
        case "showField":
          setVisibleFields((prev) => ({ ...prev, [event.target]: true }));
          break;

        // ✅ HIDE FIELD
        case "hideField":
          setVisibleFields((prev) => ({ ...prev, [event.target]: false }));
          break;

        // ✅ RESET FIELD
        case "resetField": {
          const targets = Array.isArray(event.target)
            ? event.target
            : [event.target];
          setValues((prev) => {
            const updated = { ...prev };
            targets.forEach((t) => (updated[t] = ""));
            return updated;
          });
          break;
        }

        // ✅ SET VALUE
        case "setValue":
          setValue(event.target, event.value);
          break;

        // ✅ CALL CUSTOM HANDLER
        case "call":
          if (customHandlers?.[event.handler]) {
            await customHandlers[event.handler]({
              value,
              values: updatedValues,
              setOptions,
              setValues,
              setValue,
              setVisible,
            });
          }
          break;

        default:
          break;
      }
    }
  };

  // =========================
  // 🔥 CLEAR DEPENDENCIES (RECURSIVE)
  // =========================
  const clearDependencies = (parent, updated) => {
    Object.entries(allFields).forEach(([key, field]) => {
      if (field.showWhen?.field === parent || field.dependsOn === parent) {
        updated[key] = "";
        clearDependencies(key, updated);
      }
    });
  };

  // =========================
  // 🔄 HANDLE CHANGE
  // =========================
  const handleChange = (name, value) => {
    let updatedValues = { ...values, [name]: value };

    // =========================
    // 🔥 AUTO RESET DEPENDENTS (for showWhen/dependsOn users)
    // =========================
    Object.entries(allFields).forEach(([key, field]) => {
      if (field.showWhen?.field === name || field.dependsOn === name) {
        let isMatch = false;

        if (field.showWhen) {
          if (typeof field.showWhen === "function") {
            isMatch = field.showWhen({ ...updatedValues, [name]: value });
          } else if (field.showWhen.value === "*") {
            isMatch = value !== undefined && value !== null && value !== "";
          } else if (Array.isArray(field.showWhen.value)) {
            isMatch = field.showWhen.value.includes(value);
          } else {
            isMatch = value === field.showWhen.value;
          }
        } else if (field.dependsOn === name) {
          isMatch = value !== undefined && value !== null && value !== "";
        }

        if (!isMatch) {
          updatedValues[key] = "";
          clearDependencies(key, updatedValues);
        }
      }
    });

    setValues(updatedValues);

    // ❌ Skip validation for hidden type
    if (allFields[name]?.type !== "hidden") {
      const error = validateField(
        value,
        allFields[name]?.rules,
        updatedValues
      );
      setErrors((prev) => ({ ...prev, [name]: error }));
    }

    // =========================
    // 🌐 LEGACY onChange SUPPORT (schema-level onChange callback)
    // =========================
    if (allFields[name]?.onChange) {
      allFields[name].onChange(value, {
        setOptions,
        values: updatedValues,
        setValues: (newVals) => setValues((prev) => ({ ...prev, ...newVals })),
      });
    }

    // =========================
    // 🔥 SCHEMA EVENTS ENGINE (NEW)
    // =========================
    runEvents(name, "onChange", value, updatedValues);

    // =========================
    // 🔗 NATIVE DEPENDENCY OPTIONS FETCHING (dependsOn + getOptions)
    // =========================
    Object.entries(allFields).forEach(async ([key, field]) => {
      if (field.dependsOn === name && field.getOptions) {
        if (value) {
          try {
            const resolvedOptions = await field.getOptions(updatedValues);
            setOptions(key, resolvedOptions);
          } catch (err) {
            console.error(`Failed to get options for dependent field ${key}`, err);
          }
        } else {
          setOptions(key, []);
        }
      }
    });
  };

  // =========================
  // ✅ VALIDATE ALL
  // =========================
  const validateAll = (fieldsToValidate = allFields) => {
    let newErrors = {};

    Object.keys(fieldsToValidate).forEach((key) => {
      const error = validateField(
        values[key],
        fieldsToValidate[key]?.rules,
        values
      );

      if (error) newErrors[key] = error;
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // =========================
  // 🚀 RETURN
  // =========================
  return {
    values,
    errors,
    handleChange,
    validateAll,
    dynamicOptions,
    visibleFields,  // 👈 NEW — event-driven visibility map
    setValue,
    setVisible,
    setOptions,
  };
};