"use client";
import React, { useState } from "react";
import { useForm } from "../hooks/useForm";
import { renderField } from "../core/renderField";
import "../core/field.css";
import { getVisibleFields } from "../core/getVisibleFields";

const StepForm = ({
  schema,
  onSubmit,
  apiError,
  loading,
  type,
  stepShow,
  errorType,
  percentageResult = false, // ⭐ NEW
  apiMode = false, // ✅ NEW
  answer = {},
}) => {
  const [step, setStep] = useState(0);
  const [submittedData, setSubmittedData] = useState(null); // ✅ NEW
  // const currentFields = schema.steps[step].fields;
  // const { values, errors, handleChange, validateAll } = useForm(currentFields);
  const [showPopup, setShowPopup] = useState(false);
  const [quizResult, setQuizResult] = useState(null);
  const [error, setError] = useState(null);
  const [globalError, setGlobalError] = useState(null);

  // ✅ FIX 1: MERGE ALL STEP FIELDS (IMPORTANT)
  const allFields = schema.steps.reduce((acc, step) => {
    return { ...acc, ...step.fields };
  }, {});

  const { values, errors, handleChange, validateAll, dynamicOptions } =
    useForm(allFields);

  const getMergedFields = (srcFields) => {
    let res = {};
    Object.keys(srcFields || {}).forEach((k) => {
      res[k] = {
        ...srcFields[k],
        ...(dynamicOptions?.[k] ? { options: dynamicOptions[k] } : {}),
      };
    });
    return res;
  };

  const currentFields = getMergedFields(schema.steps?.[step]?.fields || {});

  // ✅ FIX 2: SAFE visible fields
  const visibleFields = getVisibleFields(currentFields || {}, values || {});

  // const next = async () => {
  //   setGlobalError(null);

  //   const isValid = validateAll(visibleFields);

  //   if (!isValid) {
  //     setShowPopup(true);
  //     return;
  //   }

  //   const navigation = schema?.navigation;

  //   if (navigation?.onNext) {
  //     const result = await navigation.onNext({
  //       values,
  //       step,
  //       setError,
  //     });

  //     // ✅ Handle simple false
  //     if (result === false) {
  //       setGlobalError("Next is blocked");
  //       return;
  //     }

  //     if (result) {
  //       // ❌ Block but SHOW ERROR (your requirement)
  //       if (result.next === false) {
  //         setGlobalError(result.error || "Next is blocked");
  //         return;
  //       }

  //       // 🔥 Jump step
  //       if (result.goToStep !== undefined) {
  //         setStep(result.goToStep);
  //         return;
  //       }
  //     }
  //   }

  //   // ✅ Default behavior
  //   setStep((prev) => prev + 1);
  // };

  const next = async () => {
    setGlobalError(null);

    const isValid = validateAll(visibleFields);

    if (!isValid) {
      setShowPopup(true);
      return;
    }

    const navigation = schema?.navigation;

    // ✅ GET CURRENT STEP VALUES
    const currentFields = Object.keys(schema.steps[step].fields);

    const currentValues = currentFields.reduce((acc, key) => {
      acc[key] = values[key];
      return acc;
    }, {});

    if (navigation?.onNext) {
      const result = await navigation.onNext({
        values: currentValues, // ✅ ONLY CURRENT STEP
        allValues: values, // 🔥 optional full data
        step,
        setError,
      });

      if (result?.next === false) {
        setGlobalError(result.error);
        return;
      }
    }

    setStep((prev) => prev + 1);
  };

  // const prev = async () => {
  //   setGlobalError(null);

  //   const navigation = schema?.navigation;

  //   if (navigation?.onPrev) {
  //     const result = await navigation.onPrev({
  //       values,
  //       step,
  //     });

  //     if (result === false) {
  //       setGlobalError("Previous is blocked");
  //       return;
  //     }

  //     if (result) {
  //       if (result.prev === false) {
  //         setGlobalError(result.error || "Previous is blocked");
  //         return;
  //       }

  //       if (result.goToStep !== undefined) {
  //         setStep(result.goToStep);
  //         return;
  //       }
  //     }
  //   }

  //   setStep((prev) => prev - 1);
  // };

  const prev = async () => {
    setGlobalError(null);

    const navigation = schema?.navigation;

    const currentFields = Object.keys(schema.steps[step].fields);

    const currentValues = currentFields.reduce((acc, key) => {
      acc[key] = values[key];
      return acc;
    }, {});

    if (navigation?.onPrev) {
      const result = await navigation.onPrev({
        values: currentValues,
        allValues: values,
        step,
      });

      if (result?.prev === false) {
        setGlobalError(result.error);
        return;
      }
    }

    setStep((prev) => prev - 1);
  };

  const handleSubmit = async () => {
    const isValid = validateAll(visibleFields);

    if (!isValid) {
      setShowPopup(true);
      return;
    }

    const res = await onSubmit(values);

    // ❗ safer check
    if (res === false) return;

    // ⭐ QUIZ MODE
    if (percentageResult) {
      const result = calculateQuizResult(values);
      setQuizResult(result);
      return;
    }

    // ⭐ NORMAL MODE
    setSubmittedData(values);
  };

  // =========================
  // ⏳ LOADING
  // =========================
  if (loading) {
    return (
      <div className="stepper-wrapper">
        <div className="stepper-container loader-box">
          <div className="loader-spinner"></div>
          <p className="loader-text">Processing...</p>
        </div>
      </div>
    );
  }

  // =========================
  // ❌ API ERROR (FROM PROPS)
  // =========================
  if (apiError) {
    return (
      <div className="stepper-wrapper">
        <div className="stepper-container error-box">
          <h2 className="error-title">❌ Error</h2>
          <p className="error-message">{apiError}</p>
        </div>
      </div>
    );
  }

  // ✅ SUCCESS SCREEN

  if (submittedData && !apiError) {
    return (
      <div className="stepper-wrapper">
        <div className="stepper-container success-box">
          <h2 className="success-title">✅ Submitted Data</h2>

          <div className="summary-list">
            {Object.keys(submittedData).map((key) => {
              const value = submittedData[key];

              return (
                <div key={key} className="summary-item">
                  <span className="summary-label">{key}</span>

                  <span className="summary-value">
                    {(() => {
                      if (value instanceof File) return value.name;
                      if (Array.isArray(value)) return value.join(", ");
                      if (typeof value === "object" && value !== null)
                        return "-";
                      return value?.toString() || "-";
                    })()}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  // const calculateQuizResult = (values) => {
  //   let total = 0;
  //   let correct = 0;
  //   const details = [];

  //   const normalizeArray = (arr = []) => {
  //     if (!Array.isArray(arr)) return [];
  //     return [...arr].sort();
  //   };

  //   const isAnswerCorrect = (field, userAnswer) => {
  //     const correctAnswer = field.correctAnswer;

  //     // =========================
  //     // 🟢 MULTI SELECT / CHECKBOX
  //     // =========================
  //     if (Array.isArray(correctAnswer)) {
  //       const user = normalizeArray(userAnswer);
  //       const correct = normalizeArray(correctAnswer);

  //       return (
  //         Array.isArray(userAnswer) &&
  //         user.length === correct.length &&
  //         user.every((v, i) => v === correct[i])
  //       );
  //     }

  //     // =========================
  //     // 🟢 TEXT / RADIO / SINGLE
  //     // =========================
  //     return (
  //       String(userAnswer ?? "")
  //         .trim()
  //         .toLowerCase() ===
  //       String(correctAnswer ?? "")
  //         .trim()
  //         .toLowerCase()
  //     );
  //   };

  //   schema.steps.forEach((step) => {
  //     Object.entries(step.fields).forEach(([key, field]) => {
  //       if (field.correctAnswer !== undefined) {
  //         total++;

  //         const userAnswer = values[key];
  //         const isCorrect = isAnswerCorrect(field, userAnswer);

  //         if (isCorrect) correct++;

  //         details.push({
  //           question: field.label,
  //           userAnswer,
  //           correctAnswer: field.correctAnswer,
  //           isCorrect,
  //         });
  //       }
  //     });
  //   });

  //   const percentage = total ? (correct / total) * 100 : 0;

  //   return {
  //     totalQuestions: total,
  //     correctAnswers: correct,
  //     wrongAnswers: total - correct,
  //     percentage,
  //     score: `${correct}/${total}`,
  //     details,
  //   };
  // };

  const calculateQuizResult = (values) => {
    let total = 0;
    let correct = 0;
    const details = [];

    const normalizeArray = (arr = []) => {
      if (!Array.isArray(arr)) return [];
      return [...arr].sort();
    };

    const isAnswerCorrect = (field, key, userAnswer) => {
      // 🔥 choose source
      const correctAnswer = apiMode
        ? answer?.[key] // from API
        : field.correctAnswer; // from schema

      if (correctAnswer === undefined) return false;

      // ✅ MULTI SELECT
      if (Array.isArray(correctAnswer)) {
        const user = normalizeArray(userAnswer);
        const correct = normalizeArray(correctAnswer);

        return (
          Array.isArray(userAnswer) &&
          user.length === correct.length &&
          user.every((v, i) => v === correct[i])
        );
      }

      // ✅ SINGLE VALUE
      return (
        String(userAnswer ?? "")
          .trim()
          .toLowerCase() ===
        String(correctAnswer ?? "")
          .trim()
          .toLowerCase()
      );
    };

    schema.steps.forEach((step) => {
      Object.entries(step.fields).forEach(([key, field]) => {
        const correctAnswer = apiMode ? answer?.[key] : field.correctAnswer;

        if (correctAnswer !== undefined) {
          total++;

          const userAnswer = values[key];
          const isCorrect = isAnswerCorrect(field, key, userAnswer);

          if (isCorrect) correct++;

          details.push({
            question: field.label,
            userAnswer,
            correctAnswer,
            isCorrect,
          });
        }
      });
    });

    const percentage = total ? (correct / total) * 100 : 0;

    return {
      totalQuestions: total,
      correctAnswers: correct,
      wrongAnswers: total - correct,
      percentage,
      score: `${correct}/${total}`,
      details,
    };
  };

  if (quizResult) {
    return (
      <div className="stepper-wrapper">
        <div className="stepper-container success-box">
          <h2>🎯 Quiz Result</h2>

          {/* ✅ SUMMARY */}
          <div className="summary-list">
            <div className="summary-item">
              <span>Total Questions</span>
              <b>{quizResult.totalQuestions}</b>
            </div>

            <div className="summary-item">
              <span>Correct</span>
              <b>{quizResult.correctAnswers}</b>
            </div>

            <div className="summary-item">
              <span>Wrong</span>
              <b>{quizResult.wrongAnswers}</b>
            </div>

            <div className="summary-item">
              <span>Score</span>
              <b>{quizResult.score}</b>
            </div>

            <div className="summary-item">
              <span>Percentage</span>
              <b>{quizResult.percentage.toFixed(2)}%</b>
            </div>
          </div>

          <hr />

          {/* ✅ ANSWER REVIEW */}
          <h3>📋 Answer Review</h3>

          {quizResult.details.map((item, i) => {
            const formatValue = (val) => {
              if (Array.isArray(val)) return val.join(", ");
              if (val === undefined || val === null || val === "") return "-";
              return val.toString();
            };

            return (
              <div
                key={i}
                className="summary-item"
                style={{
                  flexDirection: "column",
                  alignItems: "flex-start",
                  marginBottom: "12px",
                  padding: "10px",
                  borderRadius: "6px",
                  background: item.isCorrect ? "#e8f5e9" : "#ffebee",
                }}
              >
                {/* Question */}
                <span style={{ fontWeight: "600" }}>{item.question}</span>

                {/* User Answer */}
                <span>
                  <strong>Your Answer:</strong> {formatValue(item.userAnswer)}
                </span>

                {/* Correct Answer */}
                <span>
                  <strong>Correct Answer:</strong>{" "}
                  {formatValue(item.correctAnswer)}
                </span>

                {/* Result */}
                <b
                  style={{
                    color: item.isCorrect ? "green" : "red",
                    marginTop: "4px",
                  }}
                >
                  {item.isCorrect ? "✔ Correct" : "✖ Wrong"}
                </b>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  // =========================
  // COMMON ERROR LOGIC
  // =========================
  const hasErrors = Object.entries(errors || {}).some(
    ([field, msg]) => msg && visibleFields[field],
  );

  // =========================
  // RENDER FIELD LIST
  // =========================
  const renderFields = () =>
    Object.keys(visibleFields).map((name) =>
      renderField(
        name,
        visibleFields[name],
        values[name],
        handleChange,
        errors[name],
        errorType,
      ),
    );

  // navigation buton
  const navigation = schema?.navigation;

  if (type === "layoutTwo") {
    return (
      <div className="fv-wrapper">
        <div className="fv-container">
          {/* ================= POPUP ERROR ================= */}
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors)
                    .filter(([field, msg]) => {
                      return (
                        msg &&
                        currentFields?.[field] &&
                        visibleFields?.[field] !== false // ✅ HIDE FIX
                      );
                    })
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            </div>
          )}

          {/* ================= STEP INDICATOR ================= */}
          {stepShow && (
            <div className="fv-header">
              {schema.steps.map((_, index) => (
                <React.Fragment key={index}>
                  <div className="fv-step-item">
                    <div
                      className={`fv-step-circle ${
                        index === step
                          ? "active"
                          : index < step
                            ? "completed"
                            : ""
                      }`}
                    >
                      {index < step ? "✓" : index + 1}
                    </div>

                    <span
                      className={`fv-step-label ${
                        index === step ? "active" : ""
                      }`}
                    >
                      Step {index + 1}
                    </span>
                  </div>

                  {index !== schema.steps.length - 1 && (
                    <div
                      className={`fv-step-line ${index < step ? "active" : ""}`}
                    />
                  )}
                </React.Fragment>
              ))}
            </div>
          )}

          {/* ================= BEFORE FIELD ERROR ================= */}
          {errorType === "beforField" &&
            Object.entries(errors).some(([field, msg]) => {
              return (
                msg &&
                currentFields?.[field] &&
                visibleFields?.[field] !== false // ✅ FIX
              );
            }) && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors)
                    .filter(([field, msg]) => {
                      return (
                        msg &&
                        currentFields?.[field] &&
                        visibleFields?.[field] !== false // ✅ FIX
                      );
                    })
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            )}

          {/* ================= FORM BODY ================= */}
          <div className="fv-body">
            <h2 className="fv-title">{schema.steps[step].title}</h2>

            <div className="fv-fields">
              {Object.keys(currentFields).map((name) => {
                // 🔥 HARD FIX: hide fields completely
                if (visibleFields?.[name] === false) return null;

                return renderField(
                  name,
                  currentFields[name],
                  values[name],
                  handleChange,
                  errors[name],
                  errorType,
                );
              })}
            </div>
          </div>

          <div className="step-block-error">{error}</div>
          <div className="step-block-error">{globalError}</div>

          {/* ================= FOOTER ================= */}
          <div className="fv-footer">
            {step > 0 ? (
              <button className="fv-btn fv-btn-back" onClick={prev}>
                {navigation?.prevLabel || "Previous"}
              </button>
            ) : (
              <div />
            )}

            {step === schema.steps.length - 1 ? (
              <button className="fv-btn fv-btn-submit" onClick={handleSubmit}>
                Complete Registration
              </button>
            ) : (
              <button className="fv-btn fv-btn-next" onClick={next}>
                {navigation?.nextLabel || "Continue"}
              </button>
            )}
          </div>
        </div>
      </div>
    );
  } else if (type === "layoutThree") {
    return (
      <div className="step3-wrapper">
        <div className="step3-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors)
                    .filter(([field, msg]) => {
                      // ✅ only current step fields + visible fields
                      return (
                        msg &&
                        currentFields?.[field] &&
                        visibleFields?.[field] !== false
                      );
                    })
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            </div>
          )}

          {/* --- Progress Bar --- */}
          {stepShow && (
            <div className="step3-progress">
              <div
                className="step3-progress-bar"
                style={{
                  width: `${((step + 1) / schema.steps.length) * 100}%`,
                }}
              />
            </div>
          )}

          {/* --- BEFORE FIELD ERROR SUMMARY --- */}
          {errorType === "beforField" &&
            Object.entries(errors).some(([field, msg]) => {
              return (
                msg &&
                currentFields?.[field] &&
                visibleFields?.[field] !== false
              );
            }) && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors)
                    .filter(([field, msg]) => {
                      return (
                        msg &&
                        currentFields?.[field] &&
                        visibleFields?.[field] !== false
                      );
                    })
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{currentFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            )}

          {/* --- Step Header --- */}
          <div className="step3-header">
            <h2 className="step3-title">{schema.steps[step].title}</h2>

            {stepShow && (
              <p className="step3-subtitle">
                Step {step + 1} of {schema.steps.length}
              </p>
            )}
          </div>

          {/* --- Fields --- */}
          <div className="step3-fields">
            {Object.keys(currentFields).map((name) => {
              // ❗ HARD GUARD: skip hidden fields
              if (visibleFields?.[name] === false) return null;

              return renderField(
                name,
                currentFields[name],
                values[name],
                handleChange,
                errors[name],
                errorType,
              );
            })}
          </div>

          <div className="step-block-error">{error}</div>
          <div className="step-block-error">{globalError}</div>

          {/* --- Footer --- */}
          <div className="step3-footer">
            {/* {step > 0 ? (
              <button className="step3-btn back" onClick={prev}>
                ← Back
              </button>
            ) : (
              <div />
            )}

            {step < schema.steps.length - 1 ? (
              <button className="step3-btn next" onClick={next}>
                Next →
              </button>
            ) : (
              <button className="step3-btn submit" onClick={handleSubmit}>
                Finish ✓
              </button>
            )} */}

            {step > 0 ? (
              <button className="step3-btn back" onClick={prev}>
                {navigation?.prevLabel || "← Back"}
              </button>
            ) : (
              <div />
            )}

            {step === schema.steps.length - 1 ? (
              <button className="step3-btn submit" onClick={handleSubmit}>
                Finish ✓
              </button>
            ) : (
              <button className="step3-btn next" onClick={next}>
                {navigation?.nextLabel || "Next →"}
              </button>
            )}
          </div>
        </div>
      </div>
    );
  } else {
    return (
      <div className="stepper-wrapper">
        <div className="stepper-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors || {})
                    .filter(([field, msg]) => msg && visibleFields[field]) // ✅ FIXED
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{visibleFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            </div>
          )}

          {/* --- Step Indicator --- */}
          {stepShow && (
            <div className="stepper-header">
              {schema.steps.map((_, index) => (
                <React.Fragment key={index}>
                  <div className="stepper-item">
                    <div
                      className={`stepper-circle ${
                        index === step
                          ? "active"
                          : index < step
                            ? "completed"
                            : ""
                      }`}
                    >
                      {index < step ? "✓" : index + 1}
                    </div>
                    <span
                      className={`stepper-label ${
                        index === step ? "active" : ""
                      }`}
                    >
                      Step {index + 1}
                    </span>
                  </div>
                  {index !== schema.steps.length - 1 && (
                    <div
                      className={`stepper-line ${index < step ? "active" : ""}`}
                    />
                  )}
                </React.Fragment>
              ))}
            </div>
          )}

          {/* --- BEFORE FIELD ERROR --- */}
          {errorType === "beforField" &&
            Object.entries(errors || {}).some(
              ([field, msg]) => msg && visibleFields[field], // ✅ FIXED
            ) && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors || {})
                    .filter(([field, msg]) => msg && visibleFields[field]) // ✅ FIXED
                    .map(([field, message]) => (
                      <li key={field}>
                        <strong>{visibleFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    ))}
                </ul>
              </div>
            )}

          {/* --- Form Body --- */}
          <div className="stepper-body">
            <h2 className="stepper-title">{schema.steps[step].title}</h2>

            <div className="stepper-fields">
              {Object.keys(visibleFields).map(
                (
                  name, // ✅ FIXED
                ) =>
                  renderField(
                    name,
                    visibleFields[name], // ✅ FIXED
                    values[name],
                    handleChange,
                    errors[name],
                    errorType,
                  ),
              )}
            </div>
          </div>

          <div className="step-block-error">{error}</div>
          <div className="step-block-error">{globalError}</div>

          {/* --- Footer Buttons --- */}
          <div className="stepper-footer">
            {/* {step > 0 ? (
              <button className="stepper-btn-back" onClick={prev}>
                Previous
              </button>
            ) : (
              <div />
            )}

            {step < schema.steps.length - 1 ? (
              <button className="stepper-btn-next" onClick={next}>
                Continue
              </button>
            ) : (
              <button className="stepper-btn-submit" onClick={handleSubmit}>
                Complete Registration
              </button>
            )} */}

            {step > 0 ? (
              <button className="stepper-btn-back" onClick={prev}>
                {navigation?.prevLabel || "Previous"}
              </button>
            ) : (
              <div />
            )}

            {step === schema.steps.length - 1 ? (
              <button className="stepper-btn-submit" onClick={handleSubmit}>
                {navigation?.submitLabel || "Complete Registration"}
              </button>
            ) : (
              <button className="stepper-btn-next" onClick={next}>
                {navigation?.nextLabel || "Continue"}
              </button>
            )}
          </div>
        </div>
      </div>
    );
  }
};

export default StepForm;
