export const validateField = (value, rules = {}, allValues = {}) => {
  if (!rules) return "";

  // required
  // if (rules.required && !value) {
  //   return rules.requiredMessage || "This field is Required";
  // }

  // required
  if (rules.required) {
    const isEmpty =
      value === "" ||
      value === null ||
      value === undefined ||
      (Array.isArray(value) && value.length === 0); // ✅ important

    if (isEmpty) {
      return rules.requiredMessage || "This field is Required";
    }
  }

  // minLength
  if (rules.minLength && (!value || value.length < rules.minLength)) {
    return `Minimum ${rules.minLength} characters required`;
  }

  // maxLength
  if (rules.maxLength && value?.length > rules.maxLength) {
    return `Maximum ${rules.maxLength} characters allowed`;
  }

  // email
  if (rules.email && value && !/\S+@\S+\.\S+/.test(value)) {
    return "Invalid email";
  }

  // pattern (custom regex)
  if (rules.pattern && value && !rules.pattern.test(value)) {
    return rules.patternMessage || "Invalid format";
  }

  // custom function
  // if (rules.validate) {
  //   const result = rules.validate(value);
  //   if (result !== true) return result || "Invalid value";
  // }

  if (rules.validate) {
    const result = rules.validate(value, allValues); // ✅ pass all values
    if (result !== true) return result || "Invalid value";
  }


  return "";
};