import React from "react";
import "./field.css";
import CustomMultiSelect from "../components/CustomeMultiSelect";
import CustomSelect from "../components/CustomSelect";
import PasswordField from "../components/PasswordField";

const fieldMap = {
  text: (props) => <input type="text" {...props} />,
  email: (props) => <input type="email" {...props} />,
  // password: (props) => <input type="password" {...props} />,
  textarea: (props) => <textarea {...props} />,

  // ✅ NEW: DATE FIELD
  date: (props) => <input type="date" {...props} />,

  // ✅ NEW: TIME FIELD
  time: (props) => <input type="time" {...props} />,

  // ✅ SELECT
  // select: (props, config) => (
  //   <select {...props}>
  //     <option value="">Select</option>
  //     {config.options?.map((opt, i) => (
  //       <option key={i} value={opt.value}>
  //         {opt.label}
  //       </option>
  //     ))}
  //   </select>
  // ),

  password: (props, config) => (
    <PasswordField {...props} config={config} error={props.error} />
  ),

  select: (props, config) => {
    // ✅ MULTI SELECT
    if (config.multiSelect) {
      return (
        <CustomMultiSelect
          value={props.value || []}
          onChange={props.onChange}
          options={config.options}
          placeholder={config.placeholder}
        />
      );
    }

    // ✅ SEARCHABLE SELECT
    // if (config.searchable !== false) {
    return (
      <CustomSelect
        value={props.value || ""}
        onChange={props.onChange}
        options={config.options}
        placeholder={config.placeholder}
      />
    );
    // }

    // ✅ NATIVE SELECT (Fallback)
    // return (
    //   <select {...props}>
    //     <option value="">Select</option>
    //     {config.options?.map((opt, i) => (
    //       <option key={i} value={opt.value}>
    //         {opt.label}
    //       </option>
    //     ))}
    //   </select>
    // );
  },

  // ✅ CHECKBOX (FIXED UI)
  checkbox: (props, config) => (
    <div className="checkbox-group">
      {config.options?.map((opt, i) => {
        const checked = props.value?.includes(opt.value);

        return (
          <label
            key={i}
            className={`selection-item ${checked ? "active" : ""}`}
          >
            <input
              type="checkbox"
              checked={checked}
              onChange={(e) => {
                let newValue = props.value || [];

                if (e.target.checked) {
                  newValue = [...newValue, opt.value];
                } else {
                  newValue = newValue.filter((v) => v !== opt.value);
                }

                props.onChange({ target: { value: newValue } });
              }}
            />
            <span className="custom-box"></span>
            {/* <span className="label-text">{opt.label}</span> */}
            {/* {opt.image ? (
              <img
                src={opt.image}
                alt={opt.label || "option"}
                className="checkbox-image"
              />
            ) : (
              <span className="label-text">{opt.label}</span>
            )} */}

            {opt.image ? (
              <img
                src={opt.image}
                alt={opt.label || "option"}
                className="checkbox-image"
              />
            ) : opt.icon ? (
              <span className="checkbox-image">{opt.icon}</span>
            ) : (
              <span className="label-text">{opt.label}</span>
            )}
          </label>
        );
      })}
    </div>
  ),

  // ✅ RADIO (FIXED UI)
  radio: (props, config) => (
    <div className="radio-group">
      {config.options?.map((opt, i) => {
        const checked = props.value === opt.value;

        return (
          <label
            key={i}
            className={`selection-item ${checked ? "active" : ""}`}
          >
            <input
              type="radio"
              name={props.name}
              value={opt.value}
              checked={checked}
              onChange={(e) =>
                props.onChange({ target: { value: e.target.value } })
              }
            />
            <span className="custom-radio"></span>

            {opt.image ? (
              <img
                src={opt.image}
                alt={opt.label || "option"}
                className="radio-image"
              />
            ) : opt.icon ? (
              <span className="radio-image">{opt.icon}</span>
            ) : (
              <span className="label-text">{opt.label}</span>
            )}
          </label>
        );
      })}
    </div>
  ),

  // ✅ FILE
  file: (props, config) => (
    <input
      type="file"
      accept={config.accept || "*"}
      className={props.className}
      onChange={(e) => props.onChange({ target: { value: e.target.files[0] } })}
    />
  ),

  // ✅ DROPZONE
  // dropzone: (props, config) => (
  //   <div
  //     className="dropzone"
  //     onDragOver={(e) => e.preventDefault()}
  //     onDrop={(e) => {
  //       e.preventDefault();
  //       const file = e.dataTransfer.files[0];
  //       props.onChange({ target: { value: file } });
  //     }}
  //   >
  //     {/* <p>Drag & Drop file here or click</p> */}
  //     <p>
  //       {props.value?.name
  //         ? `📄 ${props.value.name}`
  //         : "Drag & Drop file here or click to upload"}
  //     </p>
  //     <input
  //       type="file"
  //       accept={config.accept || "*"}
  //       onChange={(e) =>
  //         props.onChange({ target: { value: e.target.files[0] } })
  //       }
  //       className="dropzone-input"
  //     />
  //   </div>
  // ),

  dropzone: (props, config) => {
    const isMultiple = config.multiple;

    const handleFiles = (files) => {
      if (isMultiple) {
        const fileArray = Array.from(files);
        props.onChange({ target: { value: fileArray } });
      } else {
        props.onChange({ target: { value: files[0] } });
      }
    };

    return (
      <div
        className="dropzone"
        onDragOver={(e) => e.preventDefault()}
        onDrop={(e) => {
          e.preventDefault();
          handleFiles(e.dataTransfer.files);
        }}
      >
        {/* =========================
          FILE PREVIEW
      ========================= */}
        <p>
          {isMultiple
            ? props.value?.length
              ? `📂 ${props.value.length} files selected`
              : "Drag & Drop files here or click to upload"
            : props.value?.name
              ? `📄 ${props.value.name}`
              : "Drag & Drop file here or click to upload"}
        </p>

        {/* =========================
          INPUT
      ========================= */}
        <input
          type="file"
          accept={config.accept || "*"}
          multiple={isMultiple} // ✅ KEY CHANGE
          onChange={(e) => handleFiles(e.target.files)}
          className="dropzone-input"
        />
      </div>
    );
  },

  content: (props, config) => {
    // ✅ JSX support (best)
    if (typeof config.content === "object") {
      return <div className="form-content">{config.content}</div>;
    }

    // ✅ HTML string support
    return (
      <div
        className="form-content"
        dangerouslySetInnerHTML={{ __html: config.content || "" }}
      />
    );
  },
};

export const renderField = (
  name,
  config,
  value,
  onChange,
  error,
  errorType = "afterField",
) => {
  const FieldComponent = fieldMap[config.type];
  if (!FieldComponent) return null;

  const commonProps = {
    name,
    value:
      value ??
      (config.type === "checkbox" ||
        (config.type === "select" && config.multiSelect)
        ? []
        : ""),
    placeholder: config.placeholder || "",
    className: error ? "input error" : "input",
    onChange: (e) => onChange(name, e.target.value),
  };

  const ErrorUI =
    error &&
    (typeof error === "string" ? (
      <p className="error-text">
        {config.errorIcon && (
          <span className="error-icon">{config.errorIcon}</span>
        )}
        {config.errorImage && (
          <img src={config.errorImage} alt="error" className="error-image" />
        )}
        <span>{error}</span>
      </p>
    ) : (
      <div className="error-text">
        {config.errorIcon && (
          <span className="error-icon">{config.errorIcon}</span>
        )}
        {config.errorImage && (
          <img src={config.errorImage} alt="error" className="error-image" />
        )}
        {error} {/* ✅ JSX safe */}
      </div>
    ));

  return (
    <div className="form-group" key={name}>
      {/* {config.label && <label className="label">{config.label}</label>} */}

      {config.label && (
        <label className="label">
          {config.label}

          {config.tooltip && (
            <span className="tooltip-wrapper">
              ⓘ<span className="tooltip-text">{config.tooltip}</span>
            </span>
          )}
        </label>
      )}

      {/* ✅ BEFORE FIELD ERROR */}
      {/* {error && errorType === "beforField" && ErrorUI} */}

      {FieldComponent(commonProps, config)}

      {/* 🔹 DESCRIPTION (NEW) */}
      {config.description && (
        <p className="field-description">{config.description}</p>
      )}

      {/* ✅ AFTER FIELD ERROR */}
      {error && errorType === "afterField" && ErrorUI}
    </div>
  );
};
