"use client";
import React, { useState, useEffect, useRef } from "react";

const CustomSelect = ({ value, onChange, options, placeholder }) => {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState("");
  const ref = useRef();
  const inputRef = useRef();

  // close on outside click
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (ref.current && !ref.current.contains(e.target)) {
        setOpen(false);
      }
    };
    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, []);

  // auto focus when dropdown opens
  useEffect(() => {
    if (open && inputRef.current) {
        inputRef.current.focus();
    }
  }, [open]);

  const handleSelect = (val) => {
    onChange({ target: { value: val, name: "custom-select" } }); // emit an event-like object for the form handler
    setOpen(false);
    setSearch("");
  };

  const getLabel = (val) => options?.find((o) => o.value === val)?.label;

  const filteredOptions =
    options?.filter((opt) =>
      opt.label.toLowerCase().includes(search.toLowerCase())
    ) || [];

  return (
    <div className="custom-select" ref={ref}>
      <div 
        className="select-box" 
        onClick={() => {
          setOpen(!open);
          if (open) setSearch(""); // clear search when manually closing
        }}
      >
        {!value ? (
          <span className="placeholder">{placeholder || "Select"}</span>
        ) : (
          <span className="tag" style={{ background: "transparent", padding: 0 }}>
            {getLabel(value) || value}
          </span>
        )}

        <span className="arrow">▾</span>
      </div>

      {open && (
        <div className="dropdown">
          <div className="search-wrapper">
             <input
                ref={inputRef}
                type="text"
                className="search-input"
                placeholder="Search..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                onClick={(e) => e.stopPropagation()} // keep dropdown open
             />
          </div>
          <div className="options-container">
            {filteredOptions.length > 0 ? (
              filteredOptions.map((opt, i) => {
                const isSelected = value === opt.value;
                return (
                  <div
                    key={i}
                    className={`option ${isSelected ? "active" : ""}`}
                    onClick={(e) => {
                        e.stopPropagation();
                        handleSelect(opt.value);
                    }}
                  >
                    {opt.label}
                  </div>
                );
              })
            ) : (
              <div className="option no-results">No results found</div>
            )}
           </div>
        </div>
      )}
    </div>
  );
};

export default CustomSelect;
