"use client";
import React, { useState, useEffect, useRef } from "react";

const CustomMultiSelect = ({ value = [], onChange, options, placeholder }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef();

  // close on outside click
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (ref.current && !ref.current.contains(e.target)) {
        setOpen(false);
      }
    };
    document.addEventListener("click", handleClickOutside);
    return () => document.removeEventListener("click", handleClickOutside);
  }, []);

  const toggleOption = (val) => {
    let updated;

    if (value.includes(val)) {
      updated = value.filter((v) => v !== val);
    } else {
      updated = [...value, val];
    }

    onChange({ target: { value: updated } });
  };

  const removeItem = (val) => {
    const updated = value.filter((v) => v !== val);
    onChange({ target: { value: updated } });
  };

  const getLabel = (val) => options?.find((o) => o.value === val)?.label;

  return (
    <div className="custom-select" ref={ref}>
      <div className="select-box" onClick={() => setOpen(!open)}>
        {value.length === 0 && (
          <span className="placeholder">{placeholder || "Select"}</span>
        )}

        <div className="tags">
          {value.map((val) => (
            <span key={val} className="tag">
              {getLabel(val)}
              <span
                className="remove"
                onClick={(e) => {
                  e.stopPropagation();
                  removeItem(val);
                }}
              >
                ×
              </span>
            </span>
          ))}
        </div>

        <span className="arrow">▾</span>
      </div>

      {open && (
        <div className="dropdown">
          {options?.map((opt, i) => {
            const isSelected = value.includes(opt.value);

            return (
              <div
                key={i}
                className={`option ${isSelected ? "active" : ""}`}
                onClick={() => toggleOption(opt.value)}
              >
                <input type="checkbox" checked={isSelected} readOnly />
                {opt.label}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default CustomMultiSelect;
