// export default Form;

"use client";

import React, { useState } from "react";
import { useForm } from "../hooks/useForm";
import { renderField } from "../core/renderField";
import "../core/field.css";

const Form = ({
  schema,
  onSubmit,
  apiError,
  loading,
  errorType,
  type,
  gridType = 2,
  customHandlers = {},  // 👈 NEW: accept event-driven custom handlers
}) => {
  const {
    values,
    errors,
    handleChange,
    validateAll,
    dynamicOptions,
    visibleFields: hookVisibleFields,  // 👈 event-driven visibility from hook
  } = useForm(schema.fields, customHandlers);

  // =========================
  // 🔀 MERGE dynamic options into fields for rendering
  // =========================
  const getMergedFields = (srcFields) => {
    let res = {};
    Object.keys(srcFields || {}).forEach((k) => {
      if (srcFields[k].type === "group") {
        res[k] = { ...srcFields[k], fields: getMergedFields(srcFields[k].fields || {}) };
      } else {
        res[k] = { ...srcFields[k], ...(dynamicOptions?.[k] ? { options: dynamicOptions[k] } : {}) };
      }
    });
    return res;
  };

  const fields = getMergedFields(schema.fields);

  // =========================
  // 👁️ COMPUTE VISIBLE FIELDS
  // Combine event-driven visibility (hookVisibleFields) with
  // schema-level showWhen/dependsOn for backward compat.
  // =========================
  const flattenFields = (srcFields) => {
    let flat = {};
    Object.keys(srcFields).forEach((key) => {
      const field = srcFields[key];
      if (field.type === "group") {
        flat = { ...flat, ...flattenFields(field.fields || {}) };
      } else {
        flat[key] = field;
      }
    });
    return flat;
  };

  const flatFields = flattenFields(fields);

  // Build the effective visibleFields object:
  // - If field uses the NEW events system (has `events` or `hidden`), use hookVisibleFields.
  // - If field uses legacy showWhen/dependsOn, compute visibility the old way.
  const visibleFields = Object.fromEntries(
    Object.entries(flatFields).filter(([key, field]) => {
      // NEW event-driven system: field has events or explicit hidden flag
      if (field.events || field.hidden !== undefined) {
        return hookVisibleFields[key] !== false;
      }

      // LEGACY: showWhen
      if (field.showWhen) {
        if (typeof field.showWhen === "function") {
          return field.showWhen(values);
        }
        const depVal = values[field.showWhen.field];
        if (field.showWhen.value === "*") {
          return depVal !== undefined && depVal !== null && depVal !== "";
        }
        if (Array.isArray(field.showWhen.value)) {
          return field.showWhen.value.includes(depVal);
        }
        return depVal === field.showWhen.value;
      }

      // LEGACY: dependsOn
      if (field.dependsOn) {
        const depVal = values[field.dependsOn];
        return depVal !== undefined && depVal !== null && depVal !== "";
      }

      return true;
    })
  );

  const [submittedData, setSubmittedData] = useState(null);
  const [showPopup, setShowPopup] = useState(true);

  const handleSubmit = async (e) => {
    e.preventDefault();

    // ✅ validate only visible fields
    if (!validateAll(visibleFields)) {
      setShowPopup(true);
      return;
    }

    const res = await onSubmit(values);

    if (!apiError && res !== false) {
      setSubmittedData(values);
    }
  };

  // =========================
  // ⏳ LOADING
  // =========================
  if (loading) {
    return (
      <div className="form-wrapper">
        <div className="form-container loader-box">
          <div className="loader-spinner"></div>
          <p className="loader-text">Processing...</p>
        </div>
      </div>
    );
  }

  // =========================
  // ❌ API ERROR
  // =========================
  if (apiError) {
    return (
      <div className="form-wrapper">
        <div className="form-container error-box">
          <h2 className="error-title">❌ Error</h2>
          <p className="error-message">{apiError}</p>
        </div>
      </div>
    );
  }

  // =========================
  // ✅ SUCCESS SCREEN
  // =========================
  if (submittedData && !apiError) {
    return (
      <div className="form-wrapper">
        <div className="form-container success-box">
          <h2 className="success-title">✅ Submitted Data</h2>

          {/* <div className="summary-list">
            {Object.keys(submittedData).map((key) => {
              const value = submittedData[key];

              return (
                <div key={key} className="summary-item">
                  <span className="summary-label">{key}</span>

                  <span className="summary-value">
                    {(() => {
                      if (value instanceof File) return value.name;
                      if (Array.isArray(value)) return value.join(", ");
                      if (typeof value === "object" && value !== null)
                        return "-";
                      return value?.toString() || "-";
                    })()}
                  </span>
                </div>
              );
            })}
          </div> */}

          <div className="summary-list">
            {Object.entries(submittedData)
              .filter(([_, value]) => {
                if (value === undefined || value === null) return false;
                if (value === "") return false;

                if (Array.isArray(value) && value.length === 0) return false;

                if (typeof value === "object" && !(value instanceof File)) {
                  return Object.keys(value).length > 0;
                }

                return true;
              })
              .map(([key, value]) => {
                return (
                  <div key={key} className="summary-item">
                    <span className="summary-label">{key}</span>

                    <span className="summary-value">
                      {(() => {
                        if (value instanceof File) return value.name;
                        if (Array.isArray(value)) return value.join(", ");
                        if (typeof value === "object" && value !== null)
                          return "-";
                        return value?.toString() || "-";
                      })()}
                    </span>
                  </div>
                );
              })}
          </div>
        </div>
      </div>
    );
  }

  // =========================
  // COMMON ERROR CHECK
  // =========================
  const hasErrors = Object.entries(errors).some(
    ([field, msg]) => msg && visibleFields[field],
  );

  // const renderGroupedFields = () => {
  //   return Object.keys(fields).map((name) => {
  //     const config = fields[name];

  //     // =========================
  //     // 🔹 GROUP
  //     // =========================
  //     if (config.type === "group") {
  //       return (
  //         <div className="form-group-wrapper" key={name}>
  //           {config.label && <h3 className="group-title">{config.label}</h3>}

  //           {config.description && (
  //             <p className="group-description">{config.description}</p>
  //           )}

  //           <div className="group-fields">
  //             {Object.keys(config.fields || {}).map((childName) => {
  //               const childConfig = config.fields[childName];

  //               // ✅ APPLY showWhen (IMPORTANT)
  //               if (childConfig.showWhen) {
  //                 const { field, value } = childConfig.showWhen;
  //                 if (values[field] !== value) return null;
  //               }

  //               return renderField(
  //                 childName,
  //                 childConfig,
  //                 values[childName],
  //                 handleChange,
  //                 errors[childName],
  //                 errorType,
  //               );
  //             })}
  //           </div>
  //         </div>
  //       );
  //     }

  //     // =========================
  //     // 🔹 NORMAL FIELD
  //     // =========================
  //     if (!visibleFields[name]) return null;

  //     return renderField(
  //       name,
  //       config,
  //       values[name],
  //       handleChange,
  //       errors[name],
  //       errorType,
  //     );
  //   });
  // };

  const renderGroupedFields = (wrapperClass = "") => {
    return Object.keys(fields).map((name) => {
      const config = fields[name];

      // =========================
      // 🔹 GROUP
      // =========================
      if (config.type === "group") {
        return (
          <div className="form-group-wrapper" key={name}>
            {config.label && <h3 className="group-title">{config.label}</h3>}

            {config.description && (
              <p className="group-description">{config.description}</p>
            )}

            <div
              className="group-fields"
              style={{
                display: "grid",
                gridTemplateColumns: `repeat(${config.grid || 1}, 1fr)`,
                gap: "12px",
              }}
            >
              {Object.keys(config.fields || {}).map((childName) => {
                const childConfig = config.fields[childName];

                // ✅ ONLY CHANGE
                if (!visibleFields[childName]) return null;

                // return renderField(
                //   childName,
                //   childConfig,
                //   values[childName],
                //   handleChange,
                //   errors[childName],
                //   errorType,
                // );
                return (
                  <div className={wrapperClass} key={childName}>
                    {renderField(
                      childName,
                      childConfig,
                      values[childName],
                      handleChange,
                      errors[childName],
                      errorType,
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        );
      }

      // =========================
      // 🔹 NORMAL FIELD
      // =========================
      if (!visibleFields[name]) return null;

      return (
        <div className={wrapperClass} key={name}>
          {renderField(
            name,
            config,
            values[name],
            handleChange,
            errors[name],
            errorType,
          )}
        </div>
      );
    });
  };

  const hasGroup = Object.values(fields).some(
    (field) => field.type === "group",
  );

  // =========================
  // LAYOUT TWO
  // =========================
  if (type === "layoutTwo") {
    return (
      <div className="fv2-wrapper">
        <div className="fv2-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message || !visibleFields[field]) return null;

                    return (
                      <li key={field}>
                        <strong>{visibleFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="fv2-form">
            {errorType === "beforField" && hasErrors && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message || !visibleFields[field]) return null;

                    return (
                      <li key={field}>
                        <strong>{visibleFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}

            {/* <div
              className="fv2-grid"
              style={{ gridTemplateColumns: `repeat(${gridType}, 1fr)` }}
            >
              {Object.keys(visibleFields).map((name) => (
                <div className="fv2-field" key={name}>
                  {renderField(
                    name,
                    visibleFields[name],
                    values[name],
                    handleChange,
                    errors[name],
                    errorType,
                  )}
                </div>
              ))}
            </div> */}

            {/* {hasGroup ? (
              renderGroupedFields()
            ) : (
              <div
                className="fv2-grid"
                style={{ gridTemplateColumns: `repeat(${gridType}, 1fr)` }}
              >
                {Object.keys(visibleFields).map((name) => (
                  <div className="fv2-field" key={name}>
                    {renderField(
                      name,
                      visibleFields[name],
                      values[name],
                      handleChange,
                      errors[name],
                      errorType,
                    )}
                  </div>
                ))}
              </div>
            )} */}

            {hasGroup ? (
              <>
                {/* =========================
        🔹 GROUP + COLLECT NORMAL FIELDS
    ========================= */}
                {Object.keys(fields).map((name) => {
                  const config = fields[name];

                  // =========================
                  // 🔹 GROUP
                  // =========================
                  if (config.type === "group") {
                    return (
                      <div className="form-group-wrapper" key={name}>
                        {config.label && (
                          <h3 className="group-title">{config.label}</h3>
                        )}

                        {config.description && (
                          <p className="group-description">
                            {config.description}
                          </p>
                        )}

                        <div
                          className="group-fields"
                          style={{
                            display: "grid",
                            gridTemplateColumns: `repeat(${config.grid || 1}, 1fr)`,
                            gap: "12px",
                          }}
                        >
                          {Object.keys(config.fields || {}).map((childName) => {
                            const childConfig = config.fields[childName];

                            if (!visibleFields[childName]) return null;

                            return (
                              <div className="fv2-field" key={childName}>
                                {renderField(
                                  childName,
                                  childConfig,
                                  values[childName],
                                  handleChange,
                                  errors[childName],
                                  errorType,
                                )}
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    );
                  }

                  return null; // skip normal fields here
                })}

                {/* =========================
        🔹 NORMAL FIELDS WITH GRID
    ========================= */}
                <div
                  className="fv2-grid"
                  style={{ gridTemplateColumns: `repeat(${gridType}, 1fr)` }}
                >
                  {Object.keys(fields).map((name) => {
                    const config = fields[name];

                    if (config.type === "group") return null;
                    if (!visibleFields[name]) return null;

                    return (
                      <div className="fv2-field" key={name}>
                        {renderField(
                          name,
                          config,
                          values[name],
                          handleChange,
                          errors[name],
                          errorType,
                        )}
                      </div>
                    );
                  })}
                </div>
              </>
            ) : (
              <div
                className="fv2-grid"
                style={{ gridTemplateColumns: `repeat(${gridType}, 1fr)` }}
              >
                {Object.keys(visibleFields).map((name) => (
                  <div className="fv2-field" key={name}>
                    {renderField(
                      name,
                      visibleFields[name],
                      values[name],
                      handleChange,
                      errors[name],
                      errorType,
                    )}
                  </div>
                ))}
              </div>
            )}

            <div className="fv2-footer">
              <button type="submit" className="fv2-btn">
                Submit Details
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  // =========================
  // LAYOUT THREE
  // =========================
  else if (type === "layoutThree") {
    return (
      <div className="fv4-wrapper">
        <div className="fv4-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message || !visibleFields[field]) return null;

                    return (
                      <li key={field}>
                        <strong>{visibleFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="fv4-form">
            {errorType === "beforField" && hasErrors && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message || !visibleFields[field]) return null;

                    return (
                      <li key={field}>
                        <strong>{visibleFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}

            <div className="fv4-fields">
              {/* {Object.keys(visibleFields).map((name) => (
                <div className="fv4-field-box" key={name}>
                  {renderField(
                    name,
                    visibleFields[name],
                    values[name],
                    handleChange,
                    errors[name],
                    errorType,
                  )}
                </div>
              ))} */}
              <div className="fv4-fields">
                {hasGroup
                  ? renderGroupedFields("fv4-field-box")
                  : Object.keys(visibleFields).map((name) => (
                      <div className="fv4-field-box" key={name}>
                        {renderField(
                          name,
                          visibleFields[name],
                          values[name],
                          handleChange,
                          errors[name],
                          errorType,
                        )}
                      </div>
                    ))}
              </div>
            </div>

            <div className="fv4-footer">
              <button type="submit" className="fv4-submit">
                Submit Form
              </button>
            </div>
          </form>
        </div>
      </div>
    );
  }

  // =========================
  // DEFAULT LAYOUT
  // =========================
  else {
    return (
      <div className="form-wrapper">
        <div className="form-container">
          {errorType === "popup" && showPopup && hasErrors && (
            <div className="fv-popup-overlay">
              <div className="fv-popup">
                <div className="fv-popup-header">
                  <h3>⚠️ Please fix the following errors</h3>
                  <button
                    className="fv-popup-close"
                    onClick={() => setShowPopup(false)}
                  >
                    ✕
                  </button>
                </div>

                <ul className="fv-popup-list">
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message || !visibleFields[field]) return null;

                    return (
                      <li key={field}>
                        <strong>{visibleFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="form-content">
            {errorType === "beforField" && hasErrors && (
              <div className="fv-error-summary">
                <ul>
                  {Object.entries(errors).map(([field, message]) => {
                    if (!message || !visibleFields[field]) return null;

                    return (
                      <li key={field}>
                        <strong>{visibleFields[field]?.label || field}:</strong>{" "}
                        {message}
                      </li>
                    );
                  })}
                </ul>
              </div>
            )}

            {/* <div className="fields-grid">
              {Object.keys(visibleFields).map((name) =>
                renderField(
                  name,
                  visibleFields[name],
                  values[name],
                  handleChange,
                  errors[name],
                  errorType,
                ),
              )}
            </div> */}

            <div className="fields-grid">
              {hasGroup
                ? renderGroupedFields()
                : Object.keys(visibleFields).map((name) =>
                    renderField(
                      name,
                      visibleFields[name],
                      values[name],
                      handleChange,
                      errors[name],
                      errorType,
                    ),
                  )}
            </div>

            <button type="submit" className="submit-btn">
              Submit Details
            </button>
          </form>
        </div>
      </div>
    );
  }
};

export default Form;
